const notifyFollowsFor = `-- name: NotifyFollowsFor :many
SELECT followee_id, notify_since::timestamptz AS notify_since
FROM account_follows
WHERE follower_id = $1::bigint
  AND ended_at IS NULL
  AND notify
ORDER BY notify_since, followee_id
LIMIT $2::int
`

type NotifyFollowsForParams struct {
	FollowerID int64
	RowLimit   int32
}

type NotifyFollowsForRow struct {
	FolloweeID  int64
	NotifySince time.Time
}

// The people one account has the bell on for, with the time it was turned on
// (D-08, D-21: active follows only). The producer of follow notes reads it and
// keeps only reports posted after notify_since. Limited by the cap; ordered so
// the answer is stable.
func (q *Queries) NotifyFollowsFor(ctx context.Context, arg NotifyFollowsForParams) ([]NotifyFollowsForRow, error) {
	rows, err := q.db.Query(ctx, notifyFollowsFor, arg.FollowerID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []NotifyFollowsForRow
	for rows.Next() {
		var i NotifyFollowsForRow
		if err := rows.Scan(&i.FolloweeID, &i.NotifySince); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const personRelation = `-- name: PersonRelation :one
SELECT
    EXISTS (SELECT 1 FROM account_follows f
            WHERE f.follower_id = $1::bigint
              AND f.followee_id = $2::bigint
              AND f.ended_at IS NULL) AS viewer_follows,
    EXISTS (SELECT 1 FROM account_follows f
            WHERE f.follower_id = $2::bigint
              AND f.followee_id = $1::bigint
              AND f.ended_at IS NULL) AS follows_viewer,
    EXISTS (SELECT 1 FROM person_blocks b
            WHERE b.blocker_id = $1::bigint
              AND b.blocked_id = $2::bigint) AS viewer_blocked,
    EXISTS (SELECT 1 FROM person_blocks b
            WHERE b.blocker_id = $2::bigint
              AND b.blocked_id = $1::bigint) AS blocked_viewer
`

type PersonRelationParams struct {
	ViewerID int64
	OtherID  int64
}

type PersonRelationRow struct {
	ViewerFollows bool
	FollowsViewer bool
	ViewerBlocked bool
	BlockedViewer bool
}

// The four facts between a viewer and another person (D-12): who follows whom
// now (active rows only) and who has blocked whom.
func (q *Queries) PersonRelation(ctx context.Context, arg PersonRelationParams) (PersonRelationRow, error) {
	row := q.db.QueryRow(ctx, personRelation, arg.ViewerID, arg.OtherID)
	var i PersonRelationRow
	err := row.Scan(
		&i.ViewerFollows,
		&i.FollowsViewer,
		&i.ViewerBlocked,
		&i.BlockedViewer,
	)
	return i, err
}

const publicProfilePathsForViewer = `-- name: PublicProfilePathsForViewer :many
SELECT a.id, a.username::text AS username
FROM accounts a
WHERE a.id = ANY($1::bigint[])
  AND a.profile_public
  AND a.deleted_at IS NULL
  AND a.username IS NOT NULL
  AND a.username_screen = 'clear'
  AND NOT EXISTS (
      SELECT 1 FROM person_blocks b
      WHERE b.blocker_id = a.id AND b.blocked_id = $2::bigint)
`

type PublicProfilePathsForViewerParams struct {
	AccountIds []int64
	ViewerID   int64
}

type PublicProfilePathsForViewerRow struct {
	ID       int64
	Username string
}

// Which of these accounts have a public profile the viewer may open (D-01,
// D-12): opted in, not deleted, a clear username, and not blocking the viewer.
// A batch read for pages that link a name to its profile.
func (q *Queries) PublicProfilePathsForViewer(ctx context.Context, arg PublicProfilePathsForViewerParams) ([]PublicProfilePathsForViewerRow, error) {
	rows, err := q.db.Query(ctx, publicProfilePathsForViewer, arg.AccountIds, arg.ViewerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PublicProfilePathsForViewerRow
	for rows.Next() {
		var i PublicProfilePathsForViewerRow
		if err := rows.Scan(&i.ID, &i.Username); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setFollowNotify = `-- name: SetFollowNotify :execrows
UPDATE account_follows
SET notify = $1::boolean,
    notify_since = CASE
        WHEN $1::boolean THEN COALESCE(notify_since, $2::timestamptz)
        ELSE NULL
    END
WHERE follower_id = $3::bigint
  AND followee_id = $4::bigint
  AND ended_at IS NULL
`

type SetFollowNotifyParams struct {
	Notify     bool
	Now        time.Time
	FollowerID int64
	FolloweeID int64
}

// Turns Notify me on or off for one active follow (D-08). Turning it on keeps
// an existing notify_since, so a repeat changes nothing and a note is only for
// reports posted after the first time it was turned on; turning it off clears
// the time. Zero rows means there is no active follow (D-21). The service
// checks the relation, the mute and the cap first.
func (q *Queries) SetFollowNotify(ctx context.Context, arg SetFollowNotifyParams) (int64, error) {
	result, err := q.db.Exec(ctx, setFollowNotify,
		arg.Notify,
		arg.Now,
		arg.FollowerID,
		arg.FolloweeID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setProfilePublic = `-- name: SetProfilePublic :execrows
UPDATE accounts
SET profile_public = $1::boolean,
    profile_public_at = CASE
        WHEN $1::boolean AND NOT profile_public THEN $2::timestamptz
        ELSE profile_public_at
    END
WHERE id = $3::bigint
  AND deleted_at IS NULL
`

type SetProfilePublicParams struct {
	IsPublic bool
	Now      time.Time
	ID       int64
}

// "Let others follow me" (D-01). profile_public_at is the time the profile was
// last switched on: it moves only on a real off to on change, and a switch off
// leaves it (the accounts_profile_public_at_set check needs it set only while
// the profile is public). 0 rows means the account is deleted.
func (q *Queries) SetProfilePublic(ctx context.Context, arg SetProfilePublicParams) (int64, error) {
	result, err := q.db.Exec(ctx, setProfilePublic, arg.IsPublic, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setProfilePublicOn = `-- name: SetProfilePublicOn :execrows
UPDATE accounts
SET profile_public = true,
    profile_public_at = CASE
        WHEN NOT profile_public THEN $1::timestamptz
        ELSE profile_public_at
    END
WHERE id = $2::bigint
  AND deleted_at IS NULL
  AND display_name = $3::text
`

type SetProfilePublicOnParams struct {
	Now          time.Time
	ID           int64
	ScreenedName string
}

// Switches the profile on only while the stored Name is still the Name that was
// screened (WR-S04, review 2026-10-30). The Name screen is a slow network call;
// a Name edit that commits while it runs would otherwise go public unscreened.
// 0 rows means the account is deleted or the Name changed since the screen.
// profile_public_at moves only on a real off to on change, as in
// SetProfilePublic.
func (q *Queries) SetProfilePublicOn(ctx context.Context, arg SetProfilePublicOnParams) (int64, error) {
	result, err := q.db.Exec(ctx, setProfilePublicOn, arg.Now, arg.ID, arg.ScreenedName)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const turnOffFollowNotify = `-- name: TurnOffFollowNotify :execrows
UPDATE account_follows
SET notify = false,
    notify_since = NULL
WHERE follower_id = $1::bigint
  AND followee_id = $2::bigint
  AND ended_at IS NULL
  AND notify
`

type TurnOffFollowNotifyParams struct {
	FollowerID int64
	FolloweeID int64
}

// Turns Notify me off for one active follow, whatever it was (D-12: a mute
// turns the bell off). Zero rows means it was already off or there is no active
// follow.
func (q *Queries) TurnOffFollowNotify(ctx context.Context, arg TurnOffFollowNotifyParams) (int64, error) {
	result, err := q.db.Exec(ctx, turnOffFollowNotify, arg.FollowerID, arg.FolloweeID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const unblockAccount = `-- name: UnblockAccount :execrows
DELETE FROM person_blocks
WHERE blocker_id = $1::bigint
  AND blocked_id = $2::bigint
`

type UnblockAccountParams struct {
	BlockerID int64
	BlockedID int64
}

// Take a block back (D-12). Follows that the block ended stay ended.
func (q *Queries) UnblockAccount(ctx context.Context, arg UnblockAccountParams) (int64, error) {
	result, err := q.db.Exec(ctx, unblockAccount, arg.BlockerID, arg.BlockedID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
